from datetime import datetime, timedelta
import sqlite3

import streamlit as st

import config
import calendar_layout
import database
import friends
import gaps
import models
import recommender
import ui_components


def _navigation(connection, now):
    """Render bounded Previous/Today/Next navigation and return the selected Monday."""
    first, last = gaps.navigation_bounds(*database.get_event_date_range(connection))
    today = gaps.week_start(now)
    monday = st.session_state.get('ww_week_start', today)
    if first is not None:
        monday = min(max(monday, first), last)
    st.session_state['ww_week_start'] = monday
    with st.container(key='ww_week_buttons'):
        previous, current, following = st.columns(3)
    if previous.button('Previous week', disabled=first is None or monday <= first,
                       key='ww_previous_week'):
        st.session_state['ww_week_start'] = monday - timedelta(days=config.DAYS_PER_WEEK)
        st.rerun()
    if current.button('Today', disabled=first is None or not first <= today <= last,
                      key='ww_today'):
        st.session_state['ww_week_start'] = today
        st.rerun()
    if following.button('Next week', disabled=last is None or monday >= last,
                        key='ww_next_week'):
        st.session_state['ww_week_start'] = monday + timedelta(days=config.DAYS_PER_WEEK)
        st.rerun()
    return monday


def _confirmed_blocks(connection, start, end):
    """Read the local user's confirmations and their IDs for the public calendar blocks."""
    frame = database.get_calendar_confirmations(connection, start, end)
    blocks, ids = [], set()
    for row in frame.reset_index().to_dict('records'):
        event = models.event_from_row(row)
        blocks.append(models.BusyBlock(event.start, event.end, event.title, True, event.event_id))
        ids.add(event.event_id)
    return blocks, ids


def _day_items(day, blocks, free_gaps, now):
    """Return clipped busy blocks and non-ended gaps in chronological display order."""
    start = datetime.combine(day, datetime.min.time())
    end = start + timedelta(days=1)
    items = []
    for block in blocks:
        if block.start < end and block.end > start:
            items.append((max(start, block.start), min(end, block.end), 'busy', block))
    for gap in free_gaps:
        if gap.day == day and gap.end > now:
            items.append((gap.start, gap.end, 'gap', gap))
    return sorted(items, key=lambda item: item[0])


def _draw_day(day, labels, blocks, free_gaps, suggestions, profile, filters, now):
    """Render private busy time, public confirmations and suggestions in one day column."""
    hide_titles = st.session_state['ww_hide_busy_titles']
    heading_key = 'ww_today_heading' if day == now.date() else f'ww_day_heading_{day}'
    with st.container(key=heading_key):
        st.markdown(f'**{day:%a}** {day:%d.%m.}')
        if day == now.date():
            st.badge('Today', color='blue')
    for label in labels.get(day, []):
        st.caption('All-day entry' if hide_titles else label)
    for index, (start, end, kind, item) in enumerate(
            _day_items(day, blocks, free_gaps, now)):
        card_key = f'ww_day_card_{day}_{kind}_{index}'
        with st.container(border=True, key=card_key):
            if kind == 'gap':
                st.caption(item.label())
                ui_components.render_gap_suggestions(suggestions[item.gap_id], item,
                                                      profile, filters)
            elif item.is_weekwise:
                row = database.get_event_row(ui_components.cached_connection(),
                                              item.weekwise_event_id)
                event = models.event_from_row(row)
                ui_components.direction_badge(event.direction_key)
                st.text(event.title)
                st.caption(f'{start:%H:%M}–{end:%H:%M}')
                if event.end < now:
                    interaction = database.get_interaction(ui_components.cached_connection(),
                                                            profile.user_id, event.event_id)
                    ui_components.render_feedback_widget(interaction, 'ww_inline', now=now)
                else:
                    st.markdown('**✓ Confirmed**')
                key = f'ww_confirmed_{day}_{event.event_id}'
                if st.button('Details', key=key):
                    st.session_state['ww_open_event_id'] = event.event_id
            else:
                st.caption(f':gray[{start:%H:%M}–{end:%H:%M}]')
                st.text('Busy' if hide_titles else item.title or 'Busy')


def _choose_planning_day(day):
    """Select the recommendations tab corresponding to a clicked free calendar interval."""
    st.session_state['ww_planning_day'] = day.strftime(config.CALENDAR_DAY_LABEL)
    st.toast(day.strftime('%A') + ' selected. Activity ideas are below the calendar.')


def _slot_style(track, slot, geometry):
    """Position native containers using numeric geometry; private text never enters CSS."""
    scale = config.CALENDAR_MINUTE_HEIGHT
    inset = config.CALENDAR_SLOT_INSET
    top = geometry['offset'] * scale
    height = max(1, geometry['minutes'] * scale - inset)
    width = 100 / geometry['lanes']
    left = geometry['lane'] * width
    return (f'.st-key-{track} > [data-testid="stLayoutWrapper"]:has(> .st-key-{slot})'
            f'{{position:absolute;top:{top}px;left:calc({left}% + {inset}px);'
            f'width:calc({width}% - {inset * 2}px);height:{height}px;}}')


def _timetable_day(day, labels, blocks, free_gaps, suggestions, profile, filters, now):
    """Draw actual appointments and free intervals on the same proportional time axis."""
    today = 'today' if day == now.date() else 'day'
    with st.container(key=f'ww_calendar_header_{today}_{day}'):
        st.markdown(f'**{day:%a}**')
        st.text(f'{day:%d %b}')
        titles = labels.get(day, [])
        text = ' · '.join('All-day entry' if st.session_state['ww_hide_busy_titles'] else title
                          for title in titles)
        st.caption(text or ('Today' if day == now.date() else ' '), help=text or None)
    items = _day_items(day, blocks, free_gaps, now)
    geometry = calendar_layout.interval_layout(day, [(a, b) for a, b, _, _ in items],
                                               config.DAY_WINDOW_START, config.DAY_WINDOW_END)
    track = f'ww_track_{day}'
    rules = []
    with st.container(height=config.CALENDAR_TRACK_HEIGHT, border=False, key=track):
        for position in geometry:
            start, end, kind, item = items[position['index']]
            variant = 'free' if kind == 'gap' else 'confirmed' if item.is_weekwise else 'busy'
            slot = f'ww_slot_{day}_{variant}_{position["index"]}'
            rules.append(_slot_style(track, slot, position))
            with st.container(key=slot):
                if kind == 'gap':
                    matches = recommender.filter_suggestions(suggestions[item.gap_id], profile,
                                                              filters['bundles'],
                                                              filters['favorites'])
                    label = f'{start:%H:%M}–{end:%H:%M} · Free'
                    if matches:
                        noun = 'idea' if len(matches) == 1 else 'ideas'
                        label += f' · {len(matches)} {noun} ↓'
                    st.button(label, key=f'ww_free_{item.gap_id}', width='stretch',
                              help='Show this day’s activity suggestions below the calendar.',
                              on_click=_choose_planning_day, args=(day,))
                else:
                    private = st.session_state['ww_hide_busy_titles']
                    st.caption(f'{start:%H:%M}–{end:%H:%M}',
                               help=None if private else item.title)
                    title = item.title if not st.session_state['ww_hide_busy_titles'] else 'Busy'
                    if item.is_weekwise:
                        title = item.title
                        key = f'ww_timeline_event_{day}_{item.weekwise_event_id}'
                        if st.button('✓ ' + title, key=key, width='stretch', help=title):
                            st.session_state['ww_open_event_id'] = item.weekwise_event_id
                    else:
                        st.text(title or 'Busy')
    st.html('<style>' + ''.join(rules) + '</style>')


def _time_axis():
    """Keep hourly labels aligned with the calendar tracks without interpolating app data."""
    with st.container(key='ww_calendar_axis_header'):
        st.caption('TIME')
    labels = []
    for hour in range(config.DAY_WINDOW_START.hour, config.DAY_WINDOW_END.hour):
        offset = (hour - config.DAY_WINDOW_START.hour) * config.CALENDAR_HOUR_HEIGHT
        labels.append(f'<span style="top:{offset}px">{hour:02}:00</span>')
    st.html('<div class="ww-hour-axis">' + ''.join(labels) + '</div>')


def _planning_tabs(days, labels, blocks, free_gaps, suggestions, profile, filters, now):
    """Show compact suggestions for one day at a time while retaining all native handlers."""
    st.subheader('Make room for something good')
    st.caption('Choose a day or click a free interval above. Suggestions are possibilities; '
               'only confirmed activities occupy your calendar.')
    names = [day.strftime(config.CALENDAR_DAY_LABEL) for day in days]
    selected = st.session_state.get('ww_planning_day', now.strftime(config.CALENDAR_DAY_LABEL))
    selected = selected if selected in names else names[0]
    tabs = st.tabs(names, default=selected, key='ww_planning_day', on_change='rerun')
    for tab, day in zip(tabs, days):
        with tab:
            visible = [gap for gap in free_gaps if gap.day == day and gap.end > now]
            if not visible:
                st.caption('No remaining free gaps on this day. Choose another day.')
            for gap in visible:
                with st.container(border=True, key=f'ww_planning_gap_{gap.gap_id}'):
                    st.markdown('**' + gap.label() + '**')
                    ui_components.render_gap_suggestions(suggestions[gap.gap_id], gap,
                                                          profile, filters, column_layout=True)


def _outside_timetable(days, blocks):
    """Keep fully off-window appointments discoverable instead of silently dropping them."""
    outside = []
    for day in days:
        beginning = datetime.combine(day, config.DAY_WINDOW_START)
        ending = datetime.combine(day, config.DAY_WINDOW_END)
        for start, end, kind, block in _day_items(day, blocks, [], beginning):
            if end <= beginning or start >= ending:
                outside.append((day, start, end, block))
    if not outside:
        return
    window = f'{config.DAY_WINDOW_START:%H:%M}–{config.DAY_WINDOW_END:%H:%M}'
    with st.expander(f'Outside {window} ({len(outside)})'):
        for index, (day, start, end, block) in enumerate(outside):
            hidden = st.session_state['ww_hide_busy_titles'] and not block.is_weekwise
            title = 'Busy' if hidden else block.title or 'Busy'
            st.text(f'{day:%a %d.%m.} · {start:%H:%M}–{end:%H:%M} · {title}')
            if block.is_weekwise:
                if st.button('Details', key=f'ww_offhours_{index}_{block.weekwise_event_id}'):
                    st.session_state['ww_open_event_id'] = block.weekwise_event_id


def _render_grid(monday, labels, blocks, free_gaps, suggestions, profile, filters, now):
    """Put a real timed week first and show activity choices in a separate daily workspace."""
    days = gaps.week_days(monday)
    if st.session_state.get('ww_layout', 'Week') == 'Day':
        day = st.selectbox('Day', days, format_func=lambda value: value.strftime('%A %d.%m.'),
                           key='ww_selected_day')
        _draw_day(day, labels, blocks, free_gaps, suggestions, profile, filters, now)
        return
    st.caption('YOUR WEEK · Appointments follow the time axis. Click free time to explore ideas.')
    with st.container(key='ww_timetable'):
        columns = st.columns([0.45] + [1] * config.DAYS_PER_WEEK, gap='small')
        with columns[0]:
            _time_axis()
        for column, day in zip(columns[1:], days):
            with column:
                _timetable_day(day, labels, blocks, free_gaps, suggestions, profile, filters, now)
    _outside_timetable(days, blocks)
    _planning_tabs(days, labels, blocks, free_gaps, suggestions, profile, filters, now)


def _render_beyond(beyond, profile, filters):
    """Show off-site, trip, multi-day and outside-window events with their placement warning."""
    reasons, events = {}, []
    for event, reason in beyond:
        reasons[event.event_id] = reason
        events.append(event)
    suggestions = ui_components.score_current_events(ui_components.cached_connection(),
                                                      events, profile)
    selected = recommender.filter_suggestions(suggestions, profile, filters['bundles'],
                                              filters['favorites'])
    with st.expander(f'Beyond your gaps ({len(selected)})'):
        if not selected:
            st.caption('No matching activities beyond your gaps this week.')
        for suggestion in selected:
            event = suggestion.event
            with st.container(border=True):
                st.caption(f'{event.start:%a %d.%m.} · {reasons[event.event_id]}')
                ui_components.render_event_card(suggestion, 'ww_beyond', show_link=True)


def _week_contents(connection, start, end, now):
    """Combine private calendar blocks and public confirmations before finding free gaps."""
    confirmed, known_ids = _confirmed_blocks(connection, start, end)
    # SPEC 9.2: a cancelled export remains recognized while the user removes it externally.
    result = ui_components.load_current_calendar(
        connection, start, end, database.get_known_event_ids(connection))
    blocks, labels, recognized, used_mode, message = result
    if message:
        st.warning(message)
    blocks += confirmed
    free = []
    if used_mode != 'unavailable':
        free = gaps.find_gaps_for_week(start.date(), [(block.start, block.end) for block in blocks])
        if not free:
            st.info('Your week is full – no free gaps of 60 minutes or more.')
    events = ui_components.load_events(start, end)
    if not events:
        st.info('No activities found for this week. Try the next week.')
    placed, beyond = gaps.assign_events_to_gaps(events, free, known_ids, now)
    return blocks, labels, free, placed, beyond


def render_week(connection, now=None):
    """Show learned suggestions, filters and inline feedback for past plans."""
    now = config.local_now(now)
    with st.container(key='ww_week_navigation'):
        title_column, controls = st.columns([3, 2], vertical_alignment='center')
        with title_column:
            heading = st.empty()
        with controls:
            monday = _navigation(connection, now)
    start = datetime.combine(monday, datetime.min.time())
    end = start + timedelta(days=config.DAYS_PER_WEEK)
    heading.title(f'Week {monday.isocalendar().week} · {monday:%d.%m.} – '
             f'{(end - timedelta(days=1)):%d.%m.%Y}')
    with st.container(key='ww_week_legend'):
        for column, key in zip(st.columns(4), [*config.DIRECTION_LABELS, 'busy']):
            with column:
                if key == 'busy':
                    st.badge('Busy', color=config.BUSY_COLOR['streamlit'])
                else:
                    ui_components.direction_badge(key)
    filters = ui_components.render_filters(connection)
    profile = database.get_user_profile(connection, database.get_current_user_id(connection))
    blocks, labels, free, placed, beyond = _week_contents(connection, start, end, now)
    suggestions = {}
    invited_by = friends.pending_invitation_senders(connection, profile.user_id, now)
    scorer = ui_components.cached_recommender(*database.get_rating_cache_key(connection))
    if scorer.model is None:
        st.caption('Matches use your focus and favorites until enough ratings are available.')
    for gap_id, events in placed.items():
        suggestions[gap_id] = ui_components.score_current_events(connection, events, profile,
                                                                 now, invited_by)
    layout = st.segmented_control('Calendar view', ['Week', 'Day'],
                                  default=st.session_state.get('ww_layout', 'Week'),
                                  key='ww_layout_choice', selection_mode='single', required=True)
    st.session_state['ww_layout'] = layout
    with st.container(key='ww_week_grid'):
        _render_grid(monday, labels, blocks, free, suggestions, profile, filters, now)
    _render_beyond(beyond, profile, filters)
    ui_components.render_sidebar_status()


try:
    render_week(ui_components.cached_connection())
except (OSError, ValueError, KeyError, sqlite3.Error):
    st.error('Could not load your week. Please check your calendar input and try again.')
